// Assume Tetrahedron is std::array<Point3d, 4>
typedef std::array<Point3d, 4> Tetrahedron;

class DelaunayTriangulation3 {
public:
    typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
    typedef CGAL::Delaunay_triangulation_3<K, CGAL::Fast_location> Delaunay;
    typedef Delaunay::Point CGALPoint;
    typedef Delaunay::Cell_handle Cell_handle;
    typedef Delaunay::Finite_cells_iterator Finite_cells_iterator;

    Delaunay triangulation;

    std::vector<Tetrahedron> extractTetrahedra() const {
        std::vector<Tetrahedron> tetrahedra;
        for (Finite_cells_iterator it = triangulation.finite_cells_begin(); it != triangulation.finite_cells_end(); ++it) {
            Tetrahedron tet;
            for (int i = 0; i < 4; ++i) {
                const CGALPoint& cgalPoint = it->vertex(i)->point();
                tet[i] = Point3d(cgalPoint.x(), cgalPoint.y(), cgalPoint.z());
            }
            tetrahedra.push_back(tet);
        }
        return tetrahedra;
    }
};

